import { NextRequest, NextResponse } from 'next/server'
import { and, desc, eq } from 'drizzle-orm'
import { z } from 'zod'
import { db } from '@/lib/db'
import { products, vendorNotifications } from '@/lib/db/schema'
import { approvedVendorForCurrentUser } from '@/lib/vendor-auth'

const schema=z.object({title:z.string().trim().min(2).max(180),description:z.string().trim().max(5000),category:z.string().trim().min(1),author:z.string().trim().max(120).default(''),price:z.number().int().nonnegative(),originalPrice:z.number().int().nonnegative().nullable().optional(),stock:z.number().int().nonnegative(),cover:z.string().trim().max(2000).default(''),sku:z.string().trim().max(80),materials:z.string().trim().max(1000).default(''),dimensions:z.string().trim().max(500).default(''),weight:z.string().trim().max(100).default(''),origin:z.string().trim().max(300).default(''),specifications:z.string().trim().max(3000).default(''),tags:z.string().trim().max(500).default(''),craftType:z.string().trim().max(300).default(''),artisanInfo:z.string().trim().max(1000).default(''),regionOfOrigin:z.string().trim().max(300).default(''),giTagInfo:z.string().trim().max(500).default(''),isArchived:z.boolean().default(false),id:z.string().optional()})
const slug=(value:string)=>value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')
export async function GET(){const access=await approvedVendorForCurrentUser();if(!access)return NextResponse.json({error:'Forbidden'},{status:403});const rows=await db.select().from(products).where(eq(products.vendorId,access.vendor.id)).orderBy(desc(products.createdAt));return NextResponse.json(rows)}
export async function POST(request:NextRequest){const access=await approvedVendorForCurrentUser();if(!access)return NextResponse.json({error:'Forbidden'},{status:403});const parsed=schema.safeParse(await request.json());if(!parsed.success)return NextResponse.json({error:parsed.error.issues[0]?.message??'Please check product details.'},{status:400});const id=crypto.randomUUID();const baseSlug=slug(parsed.data.title);await db.insert(products).values({id,title:parsed.data.title,name:parsed.data.title,slug:`${baseSlug}-${id.slice(0,8)}`,sku:parsed.data.sku||`VEN-${id.slice(0,8)}`,category:parsed.data.category,vendorId:access.vendor.id,moderationStatus:'pending',description:parsed.data.description,author:parsed.data.author,price:parsed.data.price,originalPrice:parsed.data.originalPrice??null,stock:parsed.data.stock,cover:parsed.data.cover,active:false,isArchived:parsed.data.isArchived,materials:parsed.data.materials,dimensions:parsed.data.dimensions,weight:parsed.data.weight,origin:parsed.data.origin,specifications:parsed.data.specifications,tags:parsed.data.tags,craftType:parsed.data.craftType,artisanInfo:parsed.data.artisanInfo,regionOfOrigin:parsed.data.regionOfOrigin,giTagInfo:parsed.data.giTagInfo});await db.insert(vendorNotifications).values({id:crypto.randomUUID(),vendorId:access.vendor.id,type:'product_submitted',title:'Product submitted',message:`${parsed.data.title} was submitted for administrator review.`});return NextResponse.json({id,moderationStatus:'pending'}, {status:201})}
export async function PATCH(request:NextRequest){const access=await approvedVendorForCurrentUser();if(!access)return NextResponse.json({error:'Forbidden'},{status:403});const parsed=schema.safeParse(await request.json());if(!parsed.success||!parsed.data.id)return NextResponse.json({error:'Invalid product data.'},{status:400});const owned=await db.select({id:products.id}).from(products).where(and(eq(products.id,parsed.data.id),eq(products.vendorId,access.vendor.id)));if(!owned.length)return NextResponse.json({error:'Product not found'},{status:404});await db.update(products).set({title:parsed.data.title,name:parsed.data.title,description:parsed.data.description,category:parsed.data.category,author:parsed.data.author,price:parsed.data.price,originalPrice:parsed.data.originalPrice??null,stock:parsed.data.stock,cover:parsed.data.cover,sku:parsed.data.sku,materials:parsed.data.materials,dimensions:parsed.data.dimensions,weight:parsed.data.weight,origin:parsed.data.origin,specifications:parsed.data.specifications,tags:parsed.data.tags,craftType:parsed.data.craftType,artisanInfo:parsed.data.artisanInfo,regionOfOrigin:parsed.data.regionOfOrigin,giTagInfo:parsed.data.giTagInfo,isArchived:parsed.data.isArchived,moderationStatus:'pending',active:false,updatedAt:new Date()}).where(eq(products.id,parsed.data.id));return NextResponse.json({ok:true})}
export async function DELETE(request:NextRequest){const access=await approvedVendorForCurrentUser();if(!access)return NextResponse.json({error:'Forbidden'},{status:403});const id=new URL(request.url).searchParams.get('id');if(!id)return NextResponse.json({error:'Product required'},{status:400});const owned=await db.select({id:products.id}).from(products).where(and(eq(products.id,id),eq(products.vendorId,access.vendor.id)));if(!owned.length)return NextResponse.json({error:'Product not found'},{status:404});await db.update(products).set({isArchived:true,active:false,updatedAt:new Date()}).where(eq(products.id,id));return NextResponse.json({ok:true})}
